// Additional lake on the open northern ground; each vertex follows the sphere.
const openLakeDir=new T.Vector3(.12,.94,-.32).normalize(),openLakeGroup=new T.Group();openLakeGroup.name='Northern_Open_Lake';planet.add(openLakeGroup);
function openLakePoint(a,f,lift=.008){const r=1+.09*Math.sin(a*3)+.05*Math.cos(a*5),d=offset(openLakeDir,Math.cos(a)*.19*r*f,Math.sin(a)*.145*r*f);return d.multiplyScalar(terrain(d).r+lift);}
function openLakeSurface(name,color,outer,inner,lift){const vertices=[];for(let i=0;i<80;i++){const a=i/80*Math.PI*2,b=(i+1)/80*Math.PI*2,p=openLakePoint(a,outer,lift),q=openLakePoint(b,outer,lift),r=inner?openLakePoint(a,inner,lift):openLakePoint(0,0,lift),s=inner?openLakePoint(b,inner,lift):r;for(const v of [p,r,q,q,r,s])vertices.push(v.x,v.y,v.z);}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(vertices,3));geo.computeVertexNormals();const m=mesh(geo,color,openLakeGroup,{side:T.DoubleSide,roughness:.32,metalness:.06});m.name=name;return m;}
openLakeSurface('Sandy_Shore','#c5c7a1',1.12,1,.012);openLakeSurface('Shallow_Water','#95bfb0',1,0,.016);openLakeSurface('Deep_Water','#679f9d',.83,0,.019);
for(let i=0;i<17;i++){const a=i/17*Math.PI*2,p=openLakePoint(a,1.12,.015),g=new T.Group();g.position.copy(p);g.quaternion.setFromUnitVectors(up,p.clone().normalize());openLakeGroup.add(g);ball(g,i%2?'#b8baa1':'#a4b39a',0,.01,0,.025+(i%3)*.007,.015,.023);}
window.openLake={group:openLakeGroup,dir:openLakeDir,focus(){window.manhattanExplorer.exit();goal=new T.Quaternion().setFromUnitVectors(openLakeDir,new T.Vector3(0,.08,1).normalize());distance=11.6;}};
